"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77865"],{31952(e){e.exports=JSON.parse('{"id":"V4-180","slug":"federal-deposit-insurance-corporation","term":"Federal Deposit Insurance Corporation (FDIC)","also_known_as":[],"difficulty":"Beginner","definition":"The Federal Deposit Insurance Corporation (FDIC) is an independent US government agency that insures deposits at banks, supervises many banks and resolves failed banks.","explanation":["The FDIC was created by the Banking Act of 1933, during the Great Depression, after thousands of US banks failed and depositors lost their savings. Deposit insurance aimed to restore confidence and prevent bank runs.","The FDIC insures deposits at member banks up to a set limit per depositor, per bank, per ownership category. If an insured bank fails, the FDIC pays depositors their insured deposits, usually within a few days, or transfers their accounts to another bank. Since the FDIC was created, no depositor has lost insured funds.","The FDIC is funded mainly by insurance premiums paid by banks, not by taxpayers. It also supervises state-chartered banks that are not members of the Federal Reserve System and acts as receiver for failed banks, selling their assets and handling their liabilities.","For example, when Silicon Valley Bank failed in March 2023, the FDIC took control of the bank. Authorities used a special exception to protect all depositors, including those with deposits above the insurance limit, to prevent wider panic.","Credit union deposits in the United States are insured separately by the National Credit Union Administration."],"note":"","total":1725,"prev":{"slug":"favorable-variance","term":"Favorable Variance"},"next":{"slug":"federal-funds-rate","term":"Federal Funds Rate"}}')}}]);